insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_121'
from (values
('127.829.d.1.A',3,'A plant manager and a new millwright both have duties under the Occupational Safety and Health Act. Which pair of duties is correct?','["the employer provides a hazard-free workplace; the worker follows safety rules", "neither has any duty", "the employer avoids training; the worker pays for guards", "the worker writes the law; the employer ignores it"]'::jsonb,0,'Employers provide safe conditions; workers comply.','original'),
('127.829.d.1.A',4,'A worker who sees a missing machine guard and reports it is carrying out a worker responsibility to:','["avoid the employer", "help maintain a safe workplace by reporting hazards", "fix it without telling anyone", "wait for an injury"]'::jsonb,1,'Workers report hazards.','original'),
('127.829.d.1.B',3,'A maintenance supervisor explains that OSHA standards matter because they:','["approve vacation days", "set product prices", "set enforceable minimum safety requirements for workplaces", "decide employee schedules"]'::jsonb,2,'Standards protect workers.','original'),
('127.829.d.1.B',4,'A company that ignores OSHA standards on machine guarding risks:','["lower insurance costs only", "a government bonus", "no consequences", "injuries to workers and penalties from OSHA"]'::jsonb,3,'Noncompliance has consequences.','original'),
('127.829.d.1.C',3,'After a complaint about a noisy press room, a compliance officer visits the plant, inspects the area, interviews workers and meets with management afterward. This sequence describes:','["how an OSHA inspection is conducted", "a sales visit", "an employee orientation", "a vendor demo"]'::jsonb,0,'Inspections include walkthroughs and conferences.','original'),
('127.829.d.1.C',4,'During an OSHA inspection, employees have the right to:','["hide hazards", "speak privately with the inspector", "refuse any inspection", "skip training"]'::jsonb,1,'Workers may talk to inspectors.','original'),
('127.829.d.1.D',3,'Texas has state agencies that work alongside federal ones to protect worker health. The federal agency that enforces most workplace safety laws is:','["the Postal Service", "the Federal Aviation Administration", "the Occupational Safety and Health Administration", "the Library of Congress"]'::jsonb,2,'OSHA enforces workplace safety.','original'),
('127.829.d.1.D',4,'A national research institute that studies workplace hazards and recommends controls, but does not issue citations, is:','["FAA", "IRS", "OSHA", "NIOSH"]'::jsonb,3,'NIOSH researches.','original'),
('127.829.d.1.E',3,'An industrial hygienist measures dust levels, noise and chemical vapors at a plant to see if workers are exposed above safe limits. This shows how industrial hygiene:','["recognizes, evaluates and controls workplace health hazards", "builds machines", "ignores exposure", "sells products"]'::jsonb,0,'Hygiene protects health.','original'),
('127.829.d.1.E',4,'One role of industrial hygiene in preventing occupational illness is to:','["reduce training", "measure exposures and recommend controls", "delay testing", "remove warning labels"]'::jsonb,1,'Measure and control exposure.','original'),
('127.829.d.1.F',3,'A plant keeps aisles clear, uses non-slip flooring near pumps and adds handrails on stairs. These measures support:','["decorating the plant", "faster production only", "safe walking and working surfaces", "tool sales"]'::jsonb,2,'Safe surfaces prevent falls.','original'),
('127.829.d.1.F',4,'Which condition makes a walking surface hazardous in a pump room?','["a handrail", "a marked aisle", "a dry, clean floor", "an oil leak puddle on the floor"]'::jsonb,3,'Leaks cause slips.','original'),
('127.829.d.1.G',3,'To reduce slips, trips and falls, the maintenance crew cleans spills immediately, covers hoses crossing the aisle and keeps lighting bright. These are:','["best practices to prevent slips, trips and falls", "ways to hide hazards", "ways to save paint", "ways to increase accidents"]'::jsonb,0,'Housekeeping prevents falls.','original'),
('127.829.d.1.G',4,'Wearing shoes with oil-resistant soles in a plant helps prevent:','["electrical shock only", "slips on greasy floors", "eye strain", "noise damage"]'::jsonb,1,'Footwear matters.','original'),
('127.829.d.1.H',3,'A pump motor has frayed insulation exposed near the junction box. The risk from this electrical hazard is:','["nothing", "lower heat", "shock, burns or fire", "better performance"]'::jsonb,2,'Electrical hazards are serious.','original'),
('127.829.d.1.H',4,'Water on the floor near an energized pump control panel increases the risk of:','["smoother starts", "less noise", "cooler motors", "electrocution"]'::jsonb,3,'Water conducts electricity.','original'),
('127.829.d.1.I',3,'A technician locks out the disconnect, checks that the circuit is dead with a meter and wears insulating gloves. These are:','["control methods to prevent electrical hazards", "cleaning chores", "decorations", "scheduling tools"]'::jsonb,0,'De-energize and verify.','original'),
('127.829.d.1.I',4,'Ground-fault circuit interrupters in wet areas help prevent:','["noise", "electric shock", "rust", "leaks"]'::jsonb,1,'GFCIs cut power on faults.','original'),
('127.829.d.1.J',3,'A crew stores a cylinder of acetylene near an oxygen cylinder in a hot, closed storage room and transports a corrosive drum on an open cart. The analysis shows:','["no hazards", "good practice", "unsafe handling, storing and transporting of hazardous materials", "perfect safety"]'::jsonb,2,'Segregate and secure hazardous materials.','original'),
('127.829.d.1.J',4,'Why must incompatible chemicals be stored apart?','["it speeds delivery", "it saves labels", "they look different", "mixing them could cause fire, explosion or toxic gas"]'::jsonb,3,'Incompatibles can react.','original'),
('127.829.d.1.K',3,'To lower exposure to a solvent used for degreasing pump parts, the shop uses a parts washer with a lid, ventilation and chemical-resistant gloves. These steps:','["reduce exposure to hazardous materials", "slow the job only", "increase exposure", "hide the solvent"]'::jsonb,0,'Controls reduce exposure.','original'),
('127.829.d.1.K',4,'The most effective way to reduce a worker''s exposure to a hazardous solvent is to:','["wear a hat", "eliminate or substitute a less hazardous product", "ignore labels", "work faster"]'::jsonb,1,'Elimination ranks highest.','original'),
('127.829.d.1.L',3,'At the start of employment, a technician learns where the eyewash station, the first-aid kit and the emergency plan are posted. These are:','["sales lists", "menus", "workplace health and safety resources", "marketing materials"]'::jsonb,2,'Know resources.','original'),
('127.829.d.1.L',4,'An emergency plan should be available to employees so that they can:','["avoid reading it", "skip drills", "guess the steps", "know what to do and whom to call"]'::jsonb,3,'Plans guide response.','original'),
('127.829.d.1.M',3,'A plant''s safety and health program includes visible management support, worker involvement, hazard finding and training. These are:','["elements of a safety and health program", "parts of a sales plan", "pieces of a map", "elements of a payroll"]'::jsonb,0,'Program elements.','original'),
('127.829.d.1.M',4,'For a safety and health program to succeed, workers should:','["hide problems", "take part in finding and fixing hazards", "stay out of it", "avoid training"]'::jsonb,1,'Participation matters.','original'),
('127.829.d.1.N',3,'A written plan states how to report a fire, who calls 911, and which routes to take outside. This is an:','["vacation plan", "advertising plan", "emergency action plan", "pricing plan"]'::jsonb,2,'Written emergency plans.','original'),
('127.829.d.1.N',4,'Which item is required in a written emergency action plan?','["lunch menus", "vacation lists", "sales goals", "procedures for reporting emergencies and for evacuation"]'::jsonb,3,'Reporting and evacuation procedures.','original'),
('127.829.d.1.O',3,'In the pump room, a posted map shows exit routes, the outdoor assembly area and the locations of extinguishers. These are components of:','["evacuation plans and emergency exit routes", "sales pitches", "decor", "pay rates"]'::jsonb,0,'Know routes and assembly points.','original'),
('127.829.d.1.O',4,'An emergency exit door should:','["be covered with boxes", "open easily from the inside and not be blocked", "be locked", "be hidden"]'::jsonb,1,'Exits must work.','original'),
('127.829.d.1.P',3,'The plant has a fire brigade, first-aid responders and a person who calls emergency services. These workers are examples of:','["customers", "visitors", "emergency personnel within an organization", "salespeople"]'::jsonb,2,'Emergency personnel roles.','original'),
('127.829.d.1.P',4,'During an emergency, the role of trained emergency personnel is to:','["ignore the alarm", "flee without helping", "delay the response", "respond to protect people according to the plan"]'::jsonb,3,'Trained responders follow the plan.','original'),
('127.829.d.1.Q',3,'A shop labels every chemical container, keeps safety data sheets in a binder and trains staff on chemical hazards. These are:','["components of a hazard communication program", "parts of a sales plan", "elements of a menu", "parts of a travel program"]'::jsonb,0,'HazCom elements.','original'),
('127.829.d.1.Q',4,'A safety data sheet for a pump lubricant tells a worker:','["the shop''s phone number", "how to handle it safely and what to do in an exposure", "how to market it", "its resale value"]'::jsonb,1,'SDS gives hazards and first aid.','original'),
('127.829.d.1.R',3,'Before a new millwright services a compressor, the plant trains her on lockout/tagout, hazard communication and PPE. This shows:','["optional courses", "marketing training", "safety and health training requirements specified by OSHA", "payroll training"]'::jsonb,2,'OSHA requires training.','original'),
('127.829.d.1.R',4,'Safety training for a new employee should be provided:','["after an injury", "after one year", "never", "before the employee is exposed to the hazard"]'::jsonb,3,'Train before exposure.','original'),
('127.829.d.2.A',3,'Waste oil, used filters and solvent-soaked rags from servicing a pump are placed in labeled, closed containers and removed by an approved vendor. This shows:','["proper storage and disposal of hazardous materials", "leaving open", "burning on site", "dumping into drains"]'::jsonb,0,'Proper disposal protects people and the environment.','original'),
('127.829.d.2.A',4,'Used pump oil should be:','["poured in a drain", "stored in a labeled container for approved recycling or disposal", "poured on the ground", "burned in the lot"]'::jsonb,1,'Never dump used oil.','original'),
('127.829.d.2.B',3,'Before servicing a pump with a pressurized line, a technician puts on a face shield, chemical-resistant gloves and safety glasses. She is using:','["sports gear", "uniform choices", "appropriate personal protective equipment", "office clothing"]'::jsonb,2,'PPE for hazards.','original'),
('127.829.d.2.B',4,'Which PPE protects the eyes from flying chips and splashes?','["earplugs", "dust cover", "bump cap", "safety glasses or goggles"]'::jsonb,3,'Eye protection.','original'),
('127.829.d.2.C',3,'A mechanic opens the disconnect, applies a personal lock and tag to it and tries the start button to confirm the compressor will not run. This is:','["lockout/tagout", "a startup", "a lubrication check", "a cleanup"]'::jsonb,0,'LOTO controls hazardous energy.','original'),
('127.829.d.2.C',4,'After a lockout, stored energy such as air pressure must be:','["increased", "released or blocked before work starts", "left in place", "ignored"]'::jsonb,1,'Release stored energy.','original'),
('127.829.d.2.D',3,'For disassembling a pump, the technician uses a socket set, a torque wrench and a bearing puller. These are:','["garden tools only", "kitchen tools", "hand tools used for disassembly", "lab tools"]'::jsonb,2,'Hand tools for maintenance.','original'),
('127.829.d.2.D',4,'To avoid damaging a part while pulling a bearing off a shaft, the technician should use:','["a chisel", "pliers", "a hammer only", "a puller that grips the correct surface"]'::jsonb,3,'Use the right puller.','original'),
('127.829.d.2.E',3,'When using a hammer and chisel to separate a stuck flange, a technician puts on safety glasses and gloves. She is selecting:','["appropriate PPE for hand tools", "uniform colors", "decor", "tools only"]'::jsonb,0,'Match PPE to the hazard.','original'),
('127.829.d.2.E',4,'Which hazard of hand tools calls for eye protection?','["sunburn", "flying chips or debris", "slippery floors", "electrical outlets"]'::jsonb,1,'Chips fly when striking.','original'),
('127.829.d.3.A',3,'Inside a centrifugal pump, a rotating part with curved vanes throws water outward. That rotating part is the:','["check ball", "diaphragm", "impeller", "piston"]'::jsonb,2,'Impeller moves fluid.','original'),
('127.829.d.3.A',4,'Which pump part prevents liquid from leaking along the rotating shaft?','["the casing bolt", "the vane", "the label", "the mechanical seal or packing"]'::jsonb,3,'Seals contain fluid.','original'),
('127.829.d.3.B',3,'A pump that traps fluid in a cylinder and pushes it out with a moving plunger is a:','["positive displacement piston pump", "centrifugal pump", "diaphragm cover", "vacuum fan"]'::jsonb,0,'Piston pumps displace fluid.','original'),
('127.829.d.3.B',4,'In a reciprocating plunger-style pump, the moving part that slides back and forth inside the cylinder to push fluid out is the:','["impeller", "piston", "vane", "gasket"]'::jsonb,1,'The piston reciprocates.','original'),
('127.829.d.3.C',3,'A pump uses a flexible membrane that moves back and forth to draw in and push out fluid. This is a:','["centrifugal pump", "piston compressor", "diaphragm pump", "gear reducer"]'::jsonb,2,'Diaphragm pumps use a membrane.','original'),
('127.829.d.3.C',4,'A torn diaphragm in a diaphragm pump usually causes:','["quieter operation", "no change", "higher pressure", "fluid to leak or lose pressure"]'::jsonb,3,'Diaphragm failure reduces performance.','original'),
('127.829.d.3.D',3,'A pressure tank with a diaphragm placed after a pump helps:','["smooth out flow and reduce pump cycling", "stop flow", "remove water", "increase pulsation"]'::jsonb,0,'Pressure tanks buffer flow.','original'),
('127.829.d.3.D',4,'A pressure tank with a diaphragm separates:','["the tank from the floor", "the air cushion from the water", "the pump from power", "the pipe from the valve"]'::jsonb,1,'Diaphragm separates air and water.','original'),
('127.829.d.3.E',3,'Before starting a centrifugal pump above the water source, the technician fills the suction line and casing with fluid. This procedure is called:','["purging the pump", "draining the pump", "priming the pump", "cooling the pump"]'::jsonb,2,'Priming removes air.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_121'
from (values
('127.829.d.3.E',4,'A pump that runs but does not move water probably lost its:','["motor", "base", "pipe label", "prime"]'::jsonb,3,'Air in the line breaks prime.','original'),
('127.829.d.3.F',3,'A valve with a flapper or ball that lets fluid flow one way and closes against reverse flow is a:','["check valve", "gate valve", "globe valve", "relief valve"]'::jsonb,0,'Check valves are one-way.','original'),
('127.829.d.3.F',4,'The moving sealing element inside a swing check valve is the:','["impeller", "disc or flapper", "bearing", "piston ring"]'::jsonb,1,'Swing checks use a flapper.','original'),
('127.829.d.3.G',3,'A foot check valve at the end of the suction pipe keeps water in the line after the pump stops. Its function is to:','["cool the motor", "filter the water", "maintain pump priming by preventing backflow", "start the pump"]'::jsonb,2,'Check valves hold prime.','original'),
('127.829.d.3.G',4,'If the suction check valve leaks, the pump will likely:','["need no oil", "run quietly forever", "gain pressure", "lose its prime"]'::jsonb,3,'Backflow loses prime.','original'),
('127.829.d.4.A',3,'A maintenance student lays out the parts of a reciprocating air compressor: the piston, crankshaft, connecting rod, cylinder and intake and discharge valves. She is identifying:','["components of a piston compressor", "parts of a pump motor", "parts of a sprinkler", "parts of a gearbox"]'::jsonb,0,'Piston compressor parts.','original'),
('127.829.d.4.A',4,'In a piston compressor, the part that changes the motor''s rotating motion into the piston''s back-and-forth motion is the:','["tank gauge", "crankshaft and connecting rod", "intake filter", "discharge pipe"]'::jsonb,1,'Crank converts motion.','original'),
('127.829.d.4.B',3,'On the downstroke the intake valve opens and air enters the cylinder; on the upstroke the air is squeezed and pushed out the discharge valve. This describes:','["a chain breaker", "a belt tensioner", "the operation of a piston compressor", "a gear drive"]'::jsonb,2,'Intake, compression, discharge.','original'),
('127.829.d.4.B',4,'During the compression stroke of a piston compressor, the intake valve is:','["unused", "removed", "wide open the whole time", "closed while the discharge valve opens as pressure rises"]'::jsonb,3,'Valves control flow.','original'),
('127.829.d.4.C',3,'One compressor squeezes air in a single cylinder to its final pressure. Another squeezes air first in a large cylinder and then again in a smaller one. The second is a:','["two-stage compressor", "centrifugal fan", "single-stage compressor", "vacuum pump"]'::jsonb,0,'Two stages compress in steps.','original'),
('127.829.d.4.C',4,'Compared with single-stage compressors, two-stage piston compressors are usually chosen when:','["low pressure only", "higher pressure and efficiency are needed", "no pressure is needed", "no cooling is needed"]'::jsonb,1,'Two-stage reaches higher pressures efficiently.','original'),
('127.829.d.4.D',3,'Between the first and second cylinders of a two-stage compressor, a finned tube cools the air. This part is the:','["dryer", "regulator", "intercooler", "aftercooler"]'::jsonb,2,'Intercoolers cool between stages.','original'),
('127.829.d.4.D',4,'An intercooler improves a two-stage compressor by:','["heating the air more", "reducing airflow only", "adding moisture", "cooling the air before the second stage so less work is needed"]'::jsonb,3,'Cooling reduces work.','original'),
('127.829.d.4.E',3,'After the final stage, a heat exchanger cools the compressed air before it goes to the tank, causing water vapor to condense. This part is the:','["aftercooler", "valve plate", "intercooler", "filter"]'::jsonb,0,'Aftercoolers cool discharge air.','original'),
('127.829.d.4.E',4,'An aftercooler helps the system by:','["adding heat", "removing heat and condensing moisture from the discharge air", "adding oil", "removing the motor"]'::jsonb,1,'It cools and condenses water.','original'),
('127.829.d.4.F',3,'Inside the airend of a rotary screw compressor, two interlocking helical rotors turn inside a casing with bearings and seals. These screws are the:','["gears of a clock", "pistons of a piston compressor", "compression elements of a rotary screw compressor", "vanes of a pump"]'::jsonb,2,'Screws compress air.','original'),
('127.829.d.4.F',4,'Which part of a rotary screw compressor separates oil from the compressed air?','["the piston", "the diaphragm", "the crankshaft", "the oil separator"]'::jsonb,3,'Separators remove oil.','original'),
('127.829.d.4.G',3,'Air enters the inlet, is trapped between the turning screws, is squeezed as the space gets smaller and leaves at higher pressure. This describes:','["the operation of a rotary screw compressor", "a diaphragm pump", "a belt drive", "a piston compressor"]'::jsonb,0,'Screws trap and compress air.','original'),
('127.829.d.4.G',4,'A rotary screw compressor provides a continuous supply of air because:','["it uses no oil", "its screws turn steadily rather than reciprocating", "its pistons bounce", "it has no motor"]'::jsonb,1,'Rotary compressors run smoothly.','original'),
('127.829.d.4.H',3,'A plant installs a dryer after its compressor so that water does not reach pneumatic tools and valves. The dryer is important because:','["it increases noise", "it adds water", "moisture can corrode and damage air-powered equipment", "it slows airflow"]'::jsonb,2,'Dryers protect equipment.','original'),
('127.829.d.4.H',4,'One common type of dryer for compressed air chills the air so that moisture condenses and drains away. This is a:','["salt dryer", "heated dryer", "oil dryer", "refrigerated dryer"]'::jsonb,3,'Refrigerated dryers condense moisture.','original'),
('127.829.d.5.A',3,'During a PM check, a technician examines bearings for roughness, bolts for looseness, the housing for cracks and the shaft for scoring. She is:','["inspecting equipment parts", "painting parts", "moving parts", "selling parts"]'::jsonb,0,'Inspect wear points.','original'),
('127.829.d.5.A',4,'A shaft with a groove worn at the seal location should be:','["painted", "replaced or repaired", "oiled only", "ignored"]'::jsonb,1,'Worn shafts damage seals.','original'),
('127.829.d.5.B',3,'While the pump runs, a technician listens for grinding, feels for excess vibration and looks for leaks and hot spots. She is:','["ordering lunch", "shutting down the plant", "observing equipment in operation to check for potential problems", "filing papers"]'::jsonb,2,'Operational checks.','original'),
('127.829.d.5.B',4,'A rise in bearing temperature and a rising whine during operation may signal:','["normal break-in forever", "no issue", "better efficiency", "a bearing problem developing"]'::jsonb,3,'Heat and noise warn of failure.','original'),
('127.829.d.5.C',3,'After reassembling a compressor, a technician runs it, checks pressure and listens for leaks to confirm it works properly. This is:','["testing mechanical equipment after repair", "scrapping the unit", "painting it", "ordering parts"]'::jsonb,0,'Test after repair.','original'),
('127.829.d.5.C',4,'A test run after a repair should confirm:','["that the tags are removed", "correct operation, with no leaks or unusual noise", "only that it looks clean", "that the box is saved"]'::jsonb,1,'Verify function.','original'),
('127.829.d.6.A',3,'Using the equipment manual, a trainee finds the labeled parts of a pump, a compressor and a V-belt drive. She is:','["ignoring documents", "painting parts", "identifying components in manuals", "ordering lunch"]'::jsonb,2,'Manuals label components.','original'),
('127.829.d.6.A',4,'An exploded diagram in a manual is most helpful for:','["choosing the paint", "learning the price", "scheduling shifts", "seeing how parts fit together and their order of assembly"]'::jsonb,3,'Exploded diagrams guide assembly.','original'),
('127.829.d.6.B',3,'A manual says to tighten the pump flange bolts to 45 ft-lb in a crisscross pattern. The technician uses a:','["torque wrench", "measuring tape", "caliper", "pry bar"]'::jsonb,0,'Use a torque wrench to spec.','original'),
('127.829.d.6.B',4,'Over-tightening a fastener beyond the manual''s torque can:','["do nothing", "strip threads or damage the part", "make it lighter", "improve the seal forever"]'::jsonb,1,'Follow specs.','original'),
('127.829.d.6.C',3,'The nameplate on a pump shows 50 gallons per minute at 40 psi. This tells the technician the pump''s:','["warranty only", "maker''s address", "output capability", "color"]'::jsonb,2,'Nameplates list capacity.','original'),
('127.829.d.6.C',4,'A compressor rated at 10 cubic feet per minute at 125 psi has an output capability of:','["125 cfm at 10 psi", "no rating", "10 psi at 125 cfm", "10 cfm at 125 psi"]'::jsonb,3,'Match the rating.','original'),
('127.829.d.6.D',3,'A gearbox has a 4:1 reduction. If the input turns at 1,200 rpm, the output speed is:','["300 rpm", "1,200 rpm", "4,800 rpm", "600 rpm"]'::jsonb,0,'1,200 ÷ 4 = 300.','original'),
('127.829.d.6.D',4,'When a gear drive reduces speed by a ratio of 3:1, the output torque (ignoring losses) is:','["the same as the input torque", "about three times the input torque", "one third of the input torque", "zero"]'::jsonb,1,'Torque increases when speed drops.','original'),
('127.829.d.6.E',3,'Looking at a parts diagram, a technician finds the item number for a bearing and then reads the part number next to it in the parts list. She is:','["painting", "scrapping", "locating part numbers using a diagram", "guessing"]'::jsonb,2,'Diagrams link item and part numbers.','original'),
('127.829.d.6.E',4,'To order the right replacement seal, the technician should use:','["any similar seal", "the color", "a guess", "the manufacturer''s part number from the parts list"]'::jsonb,3,'Use the specified part number.','original'),
('127.829.d.6.F',3,'After replacing a bearing, a technician records the date, part number and hours on the machine''s maintenance log. This is:','["using a logbook to record information about parts", "hiding work", "painting a record", "wasting time"]'::jsonb,0,'Logbooks track work.','original'),
('127.829.d.6.F',4,'A computerized maintenance record helps a team by:','["removing history", "tracking repairs and scheduling future service", "hiding repairs", "avoiding data"]'::jsonb,1,'CMMS aids planning.','original'),
('127.829.d.7.A',3,'Before servicing a pump, a technician identifies a live motor circuit, a rotating coupling and a hot casing. These are:','["parking hazards", "office hazards", "electrical, mechanical and thermal hazards", "weather hazards only"]'::jsonb,2,'Pumps have multiple hazards.','original'),
('127.829.d.7.A',4,'A pump casing that has been running hot should be:','["sprayed with water", "touched immediately", "wrapped in cloth", "allowed to cool before it is handled"]'::jsonb,3,'Thermal hazards cause burns.','original'),
('127.829.d.7.B',3,'Locking out a pump before work is done to prevent:','["unexpected startup and release of stored energy", "a loss of paint", "tag removal", "a change of color"]'::jsonb,0,'LOTO prevents startup.','original'),
('127.829.d.7.B',4,'For a pump with pressurized piping, a lockout procedure should also include:','["removing tags", "closing and locking isolation valves and relieving pressure", "leaving valves open", "ignoring pressure"]'::jsonb,1,'Isolate fluid energy too.','original'),
('127.829.d.7.C',3,'To take apart a centrifugal pump, a technician uses a socket set to remove casing bolts, a puller for the coupling and a soft mallet to separate parts. These are:','["tools for painting", "tools for cooking", "tools and procedures for pump disassembly", "tools for gardening"]'::jsonb,2,'Disassembly requires proper tools.','original'),
('127.829.d.7.C',4,'When disassembling a pump, the technician should:','["force parts apart", "throw parts in a bin", "skip labeling", "mark or photograph parts to ensure correct reassembly"]'::jsonb,3,'Document order.','original'),
('127.829.d.7.D',3,'During reassembly, a technician installs a new mechanical seal with a clean assembly lubricant and tightens casing bolts to the specified torque in a crisscross order. This describes:','["tools and procedures for pump assembly", "a teardown", "a shipping step", "a painting step"]'::jsonb,0,'Assembly follows specs.','original'),
('127.829.d.7.D',4,'When assembling a mechanical seal, the technician should avoid:','["cleaning surfaces", "touching the sealing faces with bare fingers or dirt", "following the manual", "using the correct tools"]'::jsonb,1,'Seal faces are fragile.','original'),
('127.829.d.7.E',3,'A technician finds a pitted impeller, a scored shaft sleeve and a cracked casing during a teardown. She is:','["painting the pump", "ignoring the pump", "inspecting the pump to locate damage, defects and wear", "packing the pump"]'::jsonb,2,'Inspection identifies wear.','original'),
('127.829.d.7.E',4,'Which finding most clearly indicates cavitation damage in a pump?','["a clean impeller", "a new seal", "a tidy label", "pitting on the impeller vanes"]'::jsonb,3,'Cavitation pits metal.','original'),
('127.829.d.7.F',3,'After reassembly, a technician briefly bumps the motor to confirm the shaft turns in the direction of the arrow on the casing, then checks pressure and noise. She is:','["operating the pump to ensure correct function", "scrapping the pump", "removing the pump", "painting the pump"]'::jsonb,0,'Check rotation before running.','original'),
('127.829.d.7.F',4,'Running a centrifugal pump in the wrong direction typically causes:','["no change", "low flow and possible damage", "better efficiency", "higher flow"]'::jsonb,1,'Wrong rotation reduces performance.','original'),
('127.829.d.7.G',3,'A technician fills the bearing housing to the sight-glass line with the oil specified in the manual and checks that the oiler is working. This is:','["an inventory count", "a repair of the seal", "proper lubrication for pumps", "an electrical check"]'::jsonb,2,'Lubricate per spec.','original'),
('127.829.d.7.G',4,'Using the wrong grease in a pump bearing can cause:','["a cleaner shaft", "no effect", "a longer life", "bearing damage or early failure"]'::jsonb,3,'Use the right lubricant.','original'),
('127.829.d.7.H',3,'After rebuilding a pump, a technician enters the seal and bearing part numbers, the date and the run hours into the maintenance system. This is:','["recording information about parts and materials used", "hiding the repair", "tossing records", "erasing the history"]'::jsonb,0,'Record what was used.','original'),
('127.829.d.7.H',4,'A good maintenance record for a pump rebuild includes:','["nothing", "the date, parts used and who did the work", "only the price", "only a signature"]'::jsonb,1,'Complete records matter.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
